    for _ in range(3):
        if len(np.where(new_solution == 1)[0]) > 0 and len(np.where(new_solution == 0)[0]) > 0:
            swap_indices = np.random.choice(len(weight_lst), size=min(radius, len(weight_lst)), replace=False)
            for i in swap_indices:
